const AlarmParser = require('../../../../alarm-parser');
const DeviceProfiler = require('../../../../profiler');

const f = require('../functions');

exports.protocol = 'GT06+';
exports.model_name = 'GT06+ Enhanced';
exports.compatible_hardware = ['GT06N', 'GT06', 'GT06E', 'GT06F', 'GT06H', 'TK103', 'TK303', 'UM552'];

var adapter = function (device) {
  if (!(this instanceof adapter)) {
    return new adapter(device);
  }

  this.format = {'start': '(', 'end': ')', 'separator': ''};
  this.device = device;
  this.__count = 1;
  
  // Initialize profiler and parser
  this.profiler = new DeviceProfiler();
  this.alarmParser = new AlarmParser();

  /*******************************************
   ENHANCED PACKET PARSING WITH PROFILING
   *******************************************/
this.parse_data = function (data) {
  try {
    var hexData = this.bufferToHexString(data);
    console.log('Raw hex data received:', hexData);
    
    // Check minimum length
    if (hexData.length < 10) {
      console.log('Packet too short');
      return { cmd: 'noop', action: 'noop', device_id: '' };
    }

    var parts = {
      'raw': hexData,
      'raw_buffer': data,
      'start': hexData.substr(0, 4)
    };

    // Check for valid start bytes
    if (parts['start'] !== '7878' && parts['start'] !== '7979') {
      console.log('Invalid start bytes:', parts['start']);
      return { cmd: 'noop', action: 'noop', device_id: '' };
    }

    // Parse packet length
    parts['length'] = parseInt(hexData.substr(4, 2), 16);
    
    // Check for complete packet
    const minExpectedLength = 4 + 2 + (parts['length'] * 2) + 4;
    if (hexData.length < minExpectedLength) {
      console.log(`Incomplete packet: ${hexData.length}/${minExpectedLength}`);
      return { cmd: 'noop', action: 'noop', device_id: '' };
    }

    // Extract protocol ID
    parts['protocol_id'] = hexData.substr(6, 2).toLowerCase();
    console.log('Protocol ID:', parts['protocol_id']);
    
    // Extract data section
    const dataStart = 8;
    const dataEnd = 8 + (parts['length'] - 1) * 2;
    parts['data'] = hexData.substring(dataStart, dataStart + (parts['length'] - 1) * 2);
    
    // Extract device ID for login packets
    // Update the parse_data function to use this
    // Replace the IMEI extraction section with:
    if (parts['protocol_id'] === '01' && parts['data'].length >= 16) {
      const imei = this.extractIMEIFromHex(hexData);
      if (imei) {
        parts['device_id'] = imei;
      }
    }

    // Get device ID for analysis
    const deviceId = parts['device_id'] || (this.device.getUID ? this.device.getUID() : null);
    console.log(`Device ID for analysis: ${deviceId || 'none'}`);
    
    // Log raw data for profiling
    const connectionInfo = this.device.connection ? {
      ip: this.device.connection.remoteAddress,
      port: this.device.connection.remotePort
    } : {};
    
    // Log raw message
    this.profiler.logRawMessage(deviceId, data, 'incoming', {
      adapter: 'GT06+ Enhanced',
      protocol_id: parts['protocol_id']
    });
    
    // Analyze and profile - SIMPLIFIED VERSION
    const analysis = this.simpleAnalyzePacket(hexData, deviceId);
    parts['analysis'] = analysis;
    
    if (deviceId) {
      this.profiler.updateDeviceProfile(deviceId, analysis, connectionInfo);
    }
    
    console.log(`Analysis: Protocol=0x${analysis.protocolNumber}, Type=${analysis.packetType}, Brands=${analysis.brands.join(', ')}`);
    
    // Map protocol IDs to actions
    this.map_gt06_protocol(parts);

    console.log(`Parsed: Protocol=${parts['protocol_id']}, Action=${parts.action}, DeviceID=${parts['device_id'] || 'none'}`);
    return parts;
  } catch (error) {
    console.error('Error parsing data:', error);
    console.error('Stack:', error.stack);
    return { cmd: 'noop', action: 'noop', device_id: '' };
  }
};


this.extractIMEIFromHex = function(hexData) {
  try {
    // GT06 login packet format: 7878 0D 01 [IMEI(8 bytes)] [Serial(2 bytes)] [CRC(2 bytes)] 0D0A
    // IMEI is 8 bytes = 16 hex characters
    
    if (hexData.length < 24) {
      console.log('Hex data too short for IMEI extraction');
      return null;
    }
    
    const imeiHex = hexData.substring(8, 24); // 16 hex chars = 8 bytes
    console.log(`IMEI Hex to decode: ${imeiHex}`);
    
    // GT06 uses packed BCD format
    // Each byte contains 2 decimal digits
    let imei = '';
    
    for (let i = 0; i < imeiHex.length; i += 2) {
      const byteHex = imeiHex.substring(i, i + 2);
      const byteValue = parseInt(byteHex, 16);
      
      // Extract two decimal digits from the byte
      const digit1 = Math.floor(byteValue / 16); // High nibble
      const digit2 = byteValue % 16; // Low nibble
      
      // Convert to decimal string
      imei += digit1.toString();
      imei += digit2.toString();
    }
    
    // IMEI should be 15 digits
    if (imei.length > 15) {
      imei = imei.substring(0, 15);
    }
    
    console.log(`Decoded IMEI: ${imei} from hex ${imeiHex}`);
    return imei;
    
  } catch (error) {
    console.error('Error extracting IMEI:', error.message);
    return null;
  }
};


// Add this simple analysis method
this.simpleAnalyzePacket = function(hexString, deviceId = null) {
  const analysis = {
    timestamp: new Date().toISOString(),
    deviceId: deviceId,
    isGT06: false,
    protocolNumber: null,
    packetType: 'Unknown',
    brands: [],
    protocols: []
  };

  try {
    // Check for GT06 protocol
    if (hexString.startsWith('7878') || hexString.startsWith('7979')) {
      analysis.isGT06 = true;
      analysis.protocols.push('GT06');
      
      // Extract protocol number
      if (hexString.length >= 8) {
        analysis.protocolNumber = hexString.substring(6, 8).toLowerCase();
        
        // Map protocol numbers to types
        const protocolMap = {
          '01': 'Login',
          '10': 'GPS Data',
          '11': 'GPS Data',
          '12': 'Location Data',
          '13': 'Heartbeat/Status',
          '16': 'Alarm',
          '17': 'LBS Location',
          '1a': 'Address Query',
          '22': 'GPS + Address',
          '26': 'Alarm + Address'
        };
        
        analysis.packetType = protocolMap[analysis.protocolNumber] || 'Unknown';
      }
    }

    // Brand detection based on IMEI prefix
    if (deviceId) {
      const cleanId = deviceId.toString().replace(/\s/g, '');
      
      // Check for Teltonika
      if (cleanId.startsWith('086872') || cleanId.startsWith('86872')) {
        analysis.brands.push('Teltonika');
      }
      // Check for Queclink
      else if (cleanId.startsWith('035865') || cleanId.startsWith('35865')) {
        analysis.brands.push('Queclink');
      }
      // Check for Suntech
      else if (cleanId.startsWith('086494') || cleanId.startsWith('86494')) {
        analysis.brands.push('Suntech');
      }
      // Check for Concox
      else if (cleanId.startsWith('86108')) {
        analysis.brands.push('Concox');
      }
      // Check for Meitrack
      else if (cleanId.startsWith('86219')) {
        analysis.brands.push('Meitrack');
      }
      
      // Always add GT06 Family for GT06 devices
      if (analysis.isGT06 && analysis.brands.length === 0) {
        analysis.brands.push('GT06 Family');
      }
    }
    
  } catch (error) {
    console.error('Error in simpleAnalyzePacket:', error.message);
    analysis.error = error.message;
  }

  return analysis;
};

  this.map_gt06_protocol = function(parts) {
    const protocolMap = {
      '01': { cmd: 'login_request', action: 'login_request' },
      '10': { cmd: 'ping', action: 'ping' },
      '11': { cmd: 'ping', action: 'ping' },
      '12': { cmd: 'ping', action: 'ping' },
      '13': { cmd: 'heartbeat', action: 'heartbeat' },
      '16': { cmd: 'alarm', action: 'alarm' },
      '17': { cmd: 'lbs_location', action: 'lbs_location' },
      '18': { cmd: 'status', action: 'status' },
      '19': { cmd: 'status', action: 'status' },
      '1a': { cmd: 'alarm', action: 'alarm' },
      '1b': { cmd: 'alarm', action: 'alarm' },
      '1c': { cmd: 'alarm', action: 'alarm' },
      '22': { cmd: 'ping', action: 'ping' },
      '26': { cmd: 'alarm', action: 'alarm' },
      '27': { cmd: 'alarm', action: 'alarm' },
      '28': { cmd: 'ping', action: 'ping' },
      '2a': { cmd: 'alarm', action: 'alarm' },
      '2b': { cmd: 'alarm', action: 'alarm' },
      '2c': { cmd: 'alarm', action: 'alarm' }
    };

    const mapping = protocolMap[parts['protocol_id']] || { cmd: 'noop', action: 'noop' };
    parts.cmd = mapping.cmd;
    parts.action = mapping.action;
  };

  this.bufferToHexString = function (buffer) {
    var str = '';
    for (var i = 0; i < buffer.length; i++) {
      var hex = buffer[i].toString(16);
      str += hex.length === 1 ? '0' + hex : hex;
    }
    return str;
  };

  this.authorize = function () {
    var response = '787805010001D9DC0D0A';
    console.log('Sending login response:', response);
    
    // Log outgoing message
    const deviceId = this.device.getUID ? this.device.getUID() : null;
    this.profiler.logRawMessage(deviceId, Buffer.from(response, 'hex'), 'outgoing');
    
    this.device.send(Buffer.from(response, 'hex'));
  };
  
  this.receive_heartbeat = function (msg_parts) {
    var response = '787805130001D9DC0D0A';
    console.log('Sending heartbeat response:', response);
    
    const deviceId = this.device.getUID ? this.device.getUID() : null;
    this.profiler.logRawMessage(deviceId, Buffer.from(response, 'hex'), 'outgoing');
    
    this.device.send(Buffer.from(response, 'hex'));
  };

  /*******************************************
   ENHANCED ALARM PARSING WITH MULTI-BRAND SUPPORT
   *******************************************/
  this.receive_alarm = function (msg_parts) {
    try {
      const deviceId = msg_parts.device_id || this.device.getUID ? this.device.getUID() : null;
      const rawData = msg_parts.raw_buffer || Buffer.from(msg_parts.raw, 'hex');
      
      // Use enhanced alarm parser
      const parsedAlarm = this.alarmParser.parseAlarm(rawData, deviceId);
      
      console.log(`[Alarm] Device: ${deviceId}, Type: ${parsedAlarm.alarmType}, Brand: ${parsedAlarm.detectedBrands.join(', ')}`);
      
      return {
        code: parsedAlarm.alarmType,
        msg: parsedAlarm.alarmType,
        device_id: deviceId,
        date: new Date().toISOString(),
        timestampDate: new Date(),
        alarm_type: parsedAlarm.alarmType,
        alarm_code: parsedAlarm.alarmCode || 'unknown',
        raw_data: msg_parts.raw,
        protocol_id: msg_parts.protocol_id,
        parsed_details: parsedAlarm
      };
    } catch (error) {
      console.error('Error parsing alarm:', error);
      return false;
    }
  };

  // GPS parsing method (keep existing)
  this.get_ping_data = function (msg_parts) {
    try {
      var str = msg_parts.data_body || msg_parts.data;
      console.log('Parsing location data, length:', str.length);
      
      if (str.length >= 38) {
        return this.parse_standard_gps_data(str, msg_parts);
      } else if (str.length >= 20) {
        return this.parse_compact_gps_data(str, msg_parts);
      } else {
        console.error('GPS data too short:', str.length);
        return false;
      }
    } catch (error) {
      console.error('Error parsing ping data:', error);
      return false;
    }
  };

  this.parse_standard_gps_data = function (str, msg_parts) {
    // Parse date: 6 bytes (12 hex chars) - YYMMDDHHMMSS
    const dateHex = str.substr(0, 12);
    const year = parseInt(dateHex.substr(0, 2), 16) + 2000;
    const month = parseInt(dateHex.substr(2, 2), 16);
    const day = parseInt(dateHex.substr(4, 2), 16);
    const hour = parseInt(dateHex.substr(6, 2), 16);
    const minute = parseInt(dateHex.substr(8, 2), 16);
    const second = parseInt(dateHex.substr(10, 2), 16);
    const date = new Date(year, month - 1, day, hour, minute, second);
    
    // Parse satellites (1 byte)
    const satellites = parseInt(str.substr(12, 2), 16);
    
    // Parse latitude (4 bytes = 8 hex chars)
    const latHex = str.substr(14, 8);
    let latitude = 0;
    if (latHex !== '00000000') {
      latitude = parseInt(latHex, 16) / 1800000;
    }
    
    // Parse longitude (4 bytes = 8 hex chars)
    const lngHex = str.substr(22, 8);
    let longitude = 0;
    if (lngHex !== '00000000') {
      longitude = parseInt(lngHex, 16) / 1800000;
    }
    
    // Parse speed (1 byte)
    const speed = parseInt(str.substr(30, 2), 16);
    
    // Parse course/heading (2 bytes = 4 hex chars)
    const courseHex = str.substr(32, 4);
    let course = parseInt(courseHex, 16);
    
    // Fix course
    if (course > 360) {
      course = course & 0xFF;
      course = (course * 360) / 255;
    }
    course = Math.round(course);
    
    const data = {
      device_id: msg_parts.device_id || '',
      date: date.toISOString(),
      timestampDate: date,
      latitude: latitude,
      longitude: longitude,
      speed: speed,
      orientation: course,
      satellites: satellites,
      raw_data: str
    };
    
    console.log('Parsed location:', {
      device: data.device_id,
      lat: data.latitude,
      lng: data.longitude,
      speed: data.speed,
      course: data.orientation,
      time: data.date
    });
    
    return data;
  };

  this.parse_compact_gps_data = function (str, msg_parts) {
    const date = new Date();
    
    // Try to extract coordinates
    let latitude = 0;
    let longitude = 0;
    let speed = 0;
    
    if (str.length >= 20) {
      try {
        const latPart = str.substr(0, 8);
        const lngPart = str.substr(8, 8);
        
        if (latPart !== '00000000' && lngPart !== '00000000') {
          latitude = parseInt(latPart, 16) / 1800000;
          longitude = parseInt(lngPart, 16) / 1800000;
        }
        
        if (str.length >= 22) {
          speed = parseInt(str.substr(16, 2), 16);
        }
      } catch (e) {
        console.error('Error parsing compact GPS:', e);
      }
    }
    
    return {
      device_id: msg_parts.device_id || '',
      date: date.toISOString(),
      timestampDate: date,
      latitude: latitude,
      longitude: longitude,
      speed: speed,
      orientation: 0,
      satellites: 0,
      raw_data: str
    };
  };

  // Statistics method
  this.getStatistics = function() {
    const deviceStats = this.profiler.getDeviceSummary();
    const alarmStats = this.alarmParser.getAlarmStatistics();
    
    return {
      timestamp: new Date().toISOString(),
      device_profiles: deviceStats,
      alarm_statistics: alarmStats,
      total_raw_messages: this.profiler.profiles.size
    };
  };
};

exports.adapter = adapter;